quiet_jbs <- function(expr) suppressWarnings(suppressMessages(force(expr)))

strip_html_jbs <- function(x) {
  x <- gsub("</?[a-zA-Z][^>]*>", " ", paste(as.character(x %||% ""), collapse = " "))
  trimws(gsub("[[:space:]]+", " ", x))
}

run_jbs_test <- function(data, dep, group, grvar = NULL, counts = NULL,
                         render_plot = TRUE, render_plot2 = !is.null(grvar),
                         render_balloon = FALSE, ...) {
  args <- list(data = data, dep = dep, group = group, ...)
  if (!is.null(grvar)) args$grvar <- grvar
  if (!is.null(counts)) args$counts <- counts
  res <- quiet_jbs(do.call(jjbarstats, args))
  out <- list(
    results = res,
    notices = paste(as.character(res$notices$content %||% ""), collapse = "\n"),
    summary = strip_html_jbs(res$summary$content),
    assump  = strip_html_jbs(res$assumptions$content),
    interp  = strip_html_jbs(res$interpretation$content),
    report  = strip_html_jbs(res$report$content),
    todo    = strip_html_jbs(res$todo$content),
    plot_obj = NULL, plot_stats = NULL, plot_svg = NULL,
    plot2_obj = NULL, plot2_stats = NULL,
    balloon_obj = NULL
  )
  if (render_plot) {
    f <- tempfile(fileext = ".svg")
    svglite::svglite(f, width = 8, height = 6)
    quiet_jbs(print(res$plot))
    grDevices::dev.off()
    out$plot_obj <- ggplot2::last_plot()
    out$plot_stats <- tryCatch(ggstatsplot::extract_stats(out$plot_obj), error = function(e) NULL)
    x <- readLines(f, warn = FALSE); unlink(f)
    out$plot_svg <- paste(gsub("^>|</text>$", "", regmatches(x, regexpr(">[^<]*</text>", x))), collapse = " ")
  }
  if (render_plot2 && !is.null(grvar)) {
    f2 <- tempfile(fileext = ".svg")
    svglite::svglite(f2, width = 10, height = 6)
    quiet_jbs(print(res$plot2))
    grDevices::dev.off()
    unlink(f2)
    out$plot2_obj <- ggplot2::last_plot()
    out$plot2_stats <- tryCatch(ggstatsplot::extract_stats(out$plot2_obj), error = function(e) NULL)
  }
  if (render_balloon) {
    f3 <- tempfile(fileext = ".svg")
    svglite::svglite(f3, width = 8, height = 6)
    quiet_jbs(print(res$balloonPlot))
    grDevices::dev.off()
    unlink(f3)
    out$balloon_obj <- ggplot2::last_plot()
  }
  out
}

# Independent closed-form mathematical oracles
oracle_chisq_cramers_v <- function(tab, conf.level = 0.95) {
  n <- sum(tab)
  R <- nrow(tab); C <- ncol(tab)
  E <- outer(rowSums(tab), colSums(tab)) / n
  X2 <- sum((tab - E)^2 / E)
  df <- (R - 1) * (C - 1)
  p_val <- stats::pchisq(X2, df = df, lower.tail = FALSE)
  phi2_corr <- max(0, X2 / n - df / (n - 1))
  R_corr <- R - ((R - 1)^2) / (n - 1)
  C_corr <- C - ((C - 1)^2) / (n - 1)
  denom <- min(R_corr - 1, C_corr - 1)
  v_adj <- sqrt(phi2_corr / denom)

  alpha <- 1 - conf.level
  probs <- c(alpha / 2, 1 - alpha / 2)
  init <- rep(ifelse(X2 < 2, 2, X2 / 2), 2)
  ncp_opt <- suppressWarnings(stats::optim(par = init, fn = function(x) {
    quan <- stats::qchisq(p = probs, df = df, ncp = x)
    sum(abs(quan - X2))
  }, control = list(abstol = 1e-9)))
  ncp <- sort(ncp_opt$par)
  if (X2 <= stats::qchisq(probs[1], df)) ncp[2] <- 0
  if (X2 <= stats::qchisq(probs[2], df)) ncp[1] <- 0
  v_from_ncp <- function(lam) {
    phi_lam_adj <- sqrt(max(0, lam / n - df / (n - 1)))
    min(1, phi_lam_adj / sqrt(denom))
  }
  list(statistic = X2, df = df, p.value = p_val, estimate = v_adj,
       conf.low = v_from_ncp(ncp[1]), conf.high = v_from_ncp(ncp[2]), n = n)
}

oracle_mcnemar_cohens_g <- function(tab, conf.level = 0.95) {
  b <- tab[1, 2]; c <- tab[2, 1]
  m <- b + c
  X2 <- (b - c)^2 / m
  p_val <- stats::pchisq(X2, df = 1, lower.tail = FALSE)
  k <- max(b, c)
  g <- k / m - 0.5
  z <- stats::qnorm(1 - (1 - conf.level) / 2)
  center <- k + z^2 / 2
  half   <- z * sqrt(k * (m - k) / m + z^2 / 4)
  denom  <- m + z^2
  list(statistic = X2, df = 1L, p.value = p_val, estimate = g,
       conf.low = (center - half) / denom - 0.5,
       conf.high = (center + half) / denom - 0.5, n = sum(tab))
}

oracle_bf_indep_multi <- function(tab, a = 1) {
  C <- ncol(tab)
  row_sums <- rowSums(tab); col_sums <- colSums(tab); N <- sum(tab)
  log_p_H1 <- sum(lgamma(C * a) - C * lgamma(a) + rowSums(lgamma(tab + a)) - lgamma(row_sums + C * a))
  log_p_H0 <- (lgamma(C * a) - C * lgamma(a)) + sum(lgamma(col_sums + a)) - lgamma(N + C * a)
  list(bf10 = exp(log_p_H1 - log_p_H0), log_e_bf10 = log_p_H1 - log_p_H0)
}

