test_that("C01-C05, C14: Unpaired 2x2 Pearson chi2, Bergsma Cramer's V, CI, and GOF proportion tests match closed-form oracles", {
  # Oracle: closed-form Pearson chi2 = 1000/99, Bergsma (2013) Cramer's V, noncentral chi2 CI, and 1-way GOF chi2
  d_a1 <- data.frame(
    dep = factor(c(rep("Pos", 16), rep("Neg", 4), rep("Pos", 6), rep("Neg", 14), NA), levels = c("Pos", "Neg")),
    grp = factor(c(rep("Drug", 20), rep("Ctrl", 20), "Drug"), levels = c("Drug", "Ctrl"))
  )
  tab_a1 <- matrix(c(16, 4, 6, 14), nrow = 2, dimnames = list(c("Pos", "Neg"), c("Drug", "Ctrl")))
  ora <- oracle_chisq_cramers_v(tab_a1, conf.level = 0.95)
  res <- run_jbs_test(d_a1, dep = "dep", group = "grp", resultssubtitle = TRUE, proportiontest = TRUE)

  sd   <- res$plot_stats$subtitle_data
  desc <- res$plot_stats$descriptive_data
  ones <- res$plot_stats$one_sample_data

  expect_equal(desc$counts[order(desc$grp, desc$dep)], c(16L, 4L, 6L, 14L))
  expect_equal(desc$perc[order(desc$grp, desc$dep)], c(80, 20, 30, 70), tolerance = 1e-12)
  expect_equal(sd$statistic, 1000 / 99, tolerance = 1e-10)
  expect_equal(sd$df, 1L)
  expect_equal(sd$p.value, ora$p.value, tolerance = 1e-10)
  expect_equal(sd$estimate, ora$estimate, tolerance = 1e-10)
  expect_equal(sd$conf.low, ora$conf.low, tolerance = 1e-6)
  expect_equal(sd$conf.high, ora$conf.high, tolerance = 1e-6)
  expect_equal(sd$n.obs, 40L)

  # Per-group GOF chi2 and Pearson's C: Drug (16 vs 4 -> X2 = 7.2), Ctrl (6 vs 14 -> X2 = 3.2)
  row_drug <- ones[ones$grp == "Drug", ]
  row_ctrl <- ones[ones$grp == "Ctrl", ]
  expect_equal(row_drug$statistic, 7.2, tolerance = 1e-10)
  expect_equal(row_drug$p.value, stats::pchisq(7.2, df = 1, lower.tail = FALSE), tolerance = 1e-10)
  expect_equal(row_drug$estimate, sqrt(7.2 / 27.2), tolerance = 1e-10)
  expect_equal(row_ctrl$statistic, 3.2, tolerance = 1e-10)
})

test_that("C06: Sparse 2x2 table replaces uncorrected chi-squared subtitle with Fisher's exact test and exact OR", {
  # Oracle: stats::fisher.test hypergeometric p-value, conditional MLE odds ratio, and exact 95% CI
  d_a3 <- data.frame(
    resp = factor(rep(c("Yes", "No", "Yes", "No"), times = c(2, 10, 8, 6)), levels = c("No", "Yes")),
    arm  = factor(rep(c("A", "B"), times = c(12, 14)), levels = c("A", "B"))
  )
  ft <- stats::fisher.test(table(d_a3$resp, d_a3$arm))
  res <- run_jbs_test(d_a3, dep = "resp", group = "arm", resultssubtitle = TRUE, digits = 3)
  sub_str <- paste(deparse(res$plot_obj$labels$subtitle), collapse = " ")

  expect_true(grepl("Fisher", sub_str, fixed = TRUE))
  expect_false(grepl("Pearson", sub_str, fixed = TRUE))
  expect_true(grepl(formatC(ft$p.value, format = "f", digits = 3), sub_str, fixed = TRUE))
  expect_true(grepl(formatC(unname(ft$estimate), format = "f", digits = 3), sub_str, fixed = TRUE))
  expect_true(grepl(formatC(ft$conf.int[1], format = "f", digits = 3), sub_str, fixed = TRUE))
  expect_true(grepl(formatC(ft$conf.int[2], format = "f", digits = 3), sub_str, fixed = TRUE))
})

test_that("C08-C09: Paired 2x2 McNemar's test and Cohen's g with Wilson 95% CI match closed-form oracle", {
  # Oracle: uncorrected McNemar chi2 = (b - c)^2 / (b + c), Cohen's g = max(b,c)/(b+c) - 0.5, Wilson score CI
  d_a4 <- data.frame(
    pre  = factor(rep(c("Pos", "Pos", "Neg", "Neg"), c(20, 12, 4, 24)), levels = c("Pos", "Neg")),
    post = factor(rep(c("Pos", "Neg", "Pos", "Neg"), c(20, 12, 4, 24)), levels = c("Pos", "Neg"))
  )
  ora <- oracle_mcnemar_cohens_g(table(d_a4$pre, d_a4$post), conf.level = 0.95)
  res <- run_jbs_test(d_a4, dep = "pre", group = "post", paired = TRUE, resultssubtitle = TRUE)
  sd  <- res$plot_stats$subtitle_data

  expect_equal(sd$statistic, 4.0, tolerance = 1e-10)
  expect_equal(sd$df, 1L)
  expect_equal(sd$p.value, ora$p.value, tolerance = 1e-10)
  expect_equal(sd$estimate, 0.25, tolerance = 1e-10)
  expect_equal(sd$conf.low, ora$conf.low, tolerance = 1e-8)
  expect_equal(sd$conf.high, ora$conf.high, tolerance = 1e-8)
  expect_equal(sd$n.obs, 60L)
})

test_that("C11-C13: Bayesian Gunel-Dickey BF10, posterior Cramer's V, and bfmessage=TRUE caption match closed-form log-beta oracle", {
  # Oracle: Gunel & Dickey (1974) independent multinomial log-beta marginal likelihood (a = 1, fixed row margins)
  d_a1 <- data.frame(
    dep = factor(c(rep("Pos", 16), rep("Neg", 4), rep("Pos", 6), rep("Neg", 14)), levels = c("Pos", "Neg")),
    grp = factor(c(rep("Drug", 20), rep("Ctrl", 20)), levels = c("Drug", "Ctrl"))
  )
  ora_bf <- oracle_bf_indep_multi(table(d_a1$dep, d_a1$grp), a = 1)
  res_b  <- run_jbs_test(d_a1, dep = "dep", group = "grp", typestatistics = "bayes",
                         seed = 20250101, resultssubtitle = TRUE)
  res_f  <- run_jbs_test(d_a1, dep = "dep", group = "grp", typestatistics = "parametric",
                         bfmessage = TRUE, seed = 20250101, resultssubtitle = TRUE)

  sd_b  <- res_b$plot_stats$subtitle_data
  cap_f <- res_f$plot_stats$caption_data
  expect_equal(sd_b$bf10, ora_bf$bf10, tolerance = 1e-10)
  expect_equal(sd_b$log_e_bf10, ora_bf$log_e_bf10, tolerance = 1e-10)
  expect_equal(cap_f$bf10, ora_bf$bf10, tolerance = 1e-10)
  expect_equal(cap_f$estimate, sd_b$estimate, tolerance = 1e-12)
})

test_that("C15-C18: Weighted counts equivalence, ratio rescaling, split-by (grvar) panel additivity, and multi-dep Fisher/Pearson selection", {
  # Oracle: weighted counts table equals expanded unweighted row-level dataset
  root_dir <- if (file.exists("DESCRIPTION")) "." else if (file.exists("../../DESCRIPTION")) "../.." else getwd()
  load(file.path(root_dir, "data/jjbarstats_aggregated.rda"))
  load(file.path(root_dir, "data/jjbarstats_test.rda"))

  res_w <- run_jbs_test(jjbarstats_aggregated, dep = "response_category", group = "treatment_group",
                        counts = "count", resultssubtitle = TRUE)
  idx_exp <- rep(seq_len(nrow(jjbarstats_aggregated)), jjbarstats_aggregated$count)
  d_unw <- jjbarstats_aggregated[idx_exp, c("response_category", "treatment_group")]
  res_u <- run_jbs_test(d_unw, dep = "response_category", group = "treatment_group", resultssubtitle = TRUE)

  expect_equal(res_w$plot_stats$subtitle_data$statistic, res_u$plot_stats$subtitle_data$statistic, tolerance = 1e-10)
  expect_equal(res_w$plot_stats$subtitle_data$estimate, res_u$plot_stats$subtitle_data$estimate, tolerance = 1e-10)
  expect_equal(res_w$plot_stats$subtitle_data$n.obs, res_u$plot_stats$subtitle_data$n.obs)

  # Split-by (grvar = "sex") panel statistics match subset runs and N sums to total
  res_sp <- run_jbs_test(jjbarstats_test, dep = "response", group = "treatment",
                         grvar = "sex", resultssubtitle = TRUE, render_plot = FALSE)
  expect_equal(
    res_sp$plot2_stats[[1]]$subtitle_data$n.obs + res_sp$plot2_stats[[2]]$subtitle_data$n.obs,
    nrow(jjbarstats_test)
  )

  # Multi-dep mixed sparse + dense 2x2 applies Fisher to sparse_dep and Pearson to dense_dep
  d_multi <- data.frame(
    sparse_dep = factor(rep(c("Yes", "No", "Yes", "No"), times = c(2, 10, 8, 6)), levels = c("No", "Yes")),
    dense_dep  = factor(rep(c("Yes", "No", "Yes", "No"), times = c(9, 3, 4, 10)), levels = c("No", "Yes")),
    arm        = factor(rep(c("A", "B"), times = c(12, 14)), levels = c("A", "B"))
  )
  res_m <- run_jbs_test(d_multi, dep = c("sparse_dep", "dense_dep"), group = "arm", resultssubtitle = TRUE)
  expect_true(grepl("Fisher", res_m$plot_svg, fixed = TRUE))
  expect_true(grepl("Pearson", res_m$plot_svg, fixed = TRUE))
  expect_true(grepl("Several outcomes tested", res_m$notices, fixed = TRUE))
})

test_that("C22, C24, C28-C29: Boundary rejections, McNemar discordant guards, Cramer's V df* cutoffs, and asSource() execution", {
  # Paired McNemar boundary thresholds (N = 9 rejected; N = 10 accepted; m = 0 rejected; m = 3 WARNING; m = 4 INFO)
  mk_p <- function(a, b, c, d) {
    df <- data.frame(
      pre  = factor(rep(c("Pos", "Pos", "Neg", "Neg"), c(a, b, c, d)), levels = c("Pos", "Neg")),
      post = factor(rep(c("Pos", "Neg", "Pos", "Neg"), c(a, b, c, d)), levels = c("Pos", "Neg"))
    )
    quiet_jbs(jjbarstats(data = df, dep = "pre", group = "post", paired = TRUE))
  }
  expect_error(mk_p(3, 2, 1, 3), "fewer than 10 pairs")
  expect_no_error(mk_p(3, 3, 1, 3))
  expect_error(mk_p(10, 0, 0, 10), "No discordant pairs")
  expect_match(paste(as.character(mk_p(10, 3, 0, 10)$notices$content), collapse = " "), "cannot reach p < 0.05")
  expect_match(paste(as.character(mk_p(10, 4, 0, 10)$notices$content), collapse = " "), "little power")

  # Negative / fractional / Inf / zero counts rejected
  d_bad_cnt <- data.frame(dep = factor(c("A", "B")), grp = factor(c("X", "Y")), cnt = c(10, -2))
  expect_error(quiet_jbs(jjbarstats(data = d_bad_cnt, dep = "dep", group = "grp", counts = "cnt")), "negative values")

  # asSource() with non-ASCII / special-character column names parses and reproduces numbers
  d_utf8 <- data.frame(
    `Gréade score (%)` = factor(c(rep("Low", 15), rep("High", 5), rep("Low", 5), rep("High", 15)), levels = c("Low", "High")),
    `Treatment Arm (A/B)` = factor(c(rep("Arm A", 20), rep("Arm B", 20)), levels = c("Arm A", "Arm B")),
    check.names = FALSE
  )
  opts_u <- jjbarstatsOptions$new(dep = "Gréade score (%)", group = "Treatment Arm (A/B)", resultssubtitle = TRUE)
  a_u <- jjbarstatsClass$new(options = opts_u, data = d_utf8)
  quiet_jbs(a_u$run())
  src_u <- a_u$asSource()
  expect_no_error(base::parse(text = src_u))
})

