test_that("VAL-jjbarstats-01 (C10): Paired McNemar test and Cohen's g are invariant to opposite factor level ordering of dep and group", {
  # Same 60 paired subjects as d_a4 (20 Pos->Pos, 12 Pos->Neg, 4 Neg->Pos, 24 Neg->Neg),
  # but post has factor levels in reversed order c("Neg", "Pos").
  d_rev <- data.frame(
    pre  = factor(rep(c("Pos", "Pos", "Neg", "Neg"), c(20, 12, 4, 24)), levels = c("Pos", "Neg")),
    post = factor(rep(c("Pos", "Neg", "Pos", "Neg"), c(20, 12, 4, 24)), levels = c("Neg", "Pos"))
  )
  res <- run_jbs_test(d_rev, dep = "pre", group = "post", paired = TRUE, resultssubtitle = TRUE)
  sd  <- res$plot_stats$subtitle_data
  expect_equal(sd$statistic, 4.0, tolerance = 1e-10)
  expect_equal(sd$estimate, 0.25, tolerance = 1e-10)

  # 100% agreement (30 Pos->Pos, 20 Neg->Neg, 0 discordant pairs) with reversed factor levels must be rejected
  d_agree <- data.frame(
    pre  = factor(c(rep("Pos", 30), rep("Neg", 20)), levels = c("Pos", "Neg")),
    post = factor(c(rep("Pos", 30), rep("Neg", 20)), levels = c("Neg", "Pos"))
  )
  expect_error(quiet_jbs(jjbarstats(data = d_agree, dep = "pre", group = "post", paired = TRUE)), "No discordant pairs")
})

test_that("VAL-jjbarstats-02 (C20): Unused factor levels are dropped in .prepareData() and post-NA empty/single-level variables are rejected", {
  d_unused <- data.frame(
    dep = factor(c(rep("Pos", 16), rep("Neg", 4), rep("Pos", 6), rep("Neg", 14)), levels = c("Pos", "Neg")),
    grp = factor(c(rep("Drug", 20), rep("Ctrl", 20)), levels = c("Drug", "Ctrl", "GhostArm"))
  )
  res <- run_jbs_test(d_unused, dep = "dep", group = "grp", resultssubtitle = TRUE)
  expect_false(is.null(res$plot_obj$labels$subtitle))
  expect_match(res$summary, "across 2 groups", fixed = TRUE)
  expect_false(grepl("Low Expected Counts", res$notices, fixed = TRUE))

  # Factor dep with only 1 observed category and 1 unused category must be rejected
  d_1obs <- data.frame(
    dep = factor(rep("Pos", 20), levels = c("Pos", "Neg")),
    grp = factor(rep(c("A", "B"), each = 10), levels = c("A", "B"))
  )
  expect_error(quiet_jbs(jjbarstats(data = d_1obs, dep = "dep", group = "grp")))
})

test_that("VAL-jjbarstats-03 (C23): Assumptions panel matches resultssubtitle=FALSE and typestatistics='bayes' on sparse 2x2 tables", {
  d_sp <- data.frame(
    resp = factor(rep(c("Yes", "No", "Yes", "No"), times = c(2, 10, 8, 6)), levels = c("No", "Yes")),
    arm  = factor(rep(c("A", "B"), times = c(12, 14)), levels = c("A", "B"))
  )
  res_nosub <- run_jbs_test(d_sp, dep = "resp", group = "arm", resultssubtitle = FALSE, render_plot = FALSE)
  expect_false(grepl("subtitle reports Fisher's exact test", res_nosub$assump, fixed = TRUE))

  res_bayes <- run_jbs_test(d_sp, dep = "resp", group = "arm", typestatistics = "bayes",
                            resultssubtitle = TRUE, render_plot = FALSE)
  expect_false(grepl("Pearson chi-squared", res_bayes$assump, fixed = TRUE))
})

